struct Badge: View {
  var body: some View {
    Text("Sale")
      .padding(8)                      // proposes (offered size - 16) to the Text
      .background(.pink)               // sizes itself around the padded text
      .frame(width: 200, height: 60)   // a NEW parent 200x60; the badge centres inside it
  }
}

// .frame never resizes the child. It proposes a size and positions whatever comes back.
Text(longString).frame(width: 100)           // Text wraps into 100pt
Image("logo").frame(width: 100)              // fixed-size image is centred, not scaled
Image("logo").resizable().frame(width: 100)  // resizable accepts any proposal

// A nil proposal asks "what is your ideal size?" — that is what fixedSize sends
Text(paragraph)
  .fixedSize(horizontal: false, vertical: true)   // stop the vertical truncation

// Greedy views take everything offered
HStack {
  Text("Left")
  Spacer()        // handed .infinity, so it absorbs the slack
  Text("Right")
}

// GeometryReader returns the whole proposal, which is why it expands
GeometryReader { proxy in
  Chart(data).frame(width: proxy.size.width * 0.5)
}
.frame(height: 200)   // bound it, or it eats the enclosing stack

