// A custom guide lines up views in unrelated branches
private enum PriceAlignment: AlignmentID {
  static func defaultValue(in d: ViewDimensions) -> CGFloat { d[.trailing] }
}

extension HorizontalAlignment {
  static let price = HorizontalAlignment(PriceAlignment.self)
}

VStack(alignment: .price) {
  ForEach(items) { item in
    HStack {
      Text(item.name)
      Spacer()
      Text(item.price).alignmentGuide(.price) { $0[.leading] }
    }
