// Wrong: a bundled image ignores the proposed size until it is resizable
Image("cover").frame(width: 120, height: 120)   // still full size, just overflowing

// Right: resizable, then a content mode, then clip what .fill spills
Image("cover")
  .resizable()
  .scaledToFill()
  .frame(width: 120, height: 120)
  .clipped()                                    // without this it paints over its neighbours
  .clipShape(.rect(cornerRadius: 12))

// SF Symbols are text: size them with font/imageScale, never .resizable()
Image(systemName: "bell.badge")
  .font(.title2)
  .imageScale(.large)
  .symbolRenderingMode(.hierarchical)
  .foregroundStyle(.tint)

// AsyncImage: phases give you a real failure branch
AsyncImage(url: item.thumbnailURL, transaction: .init(animation: .default)) { phase in
  switch phase {
  case .success(let image): image.resizable().scaledToFill()
  case .failure:            Image(systemName: "photo")
  case .empty:              Color.secondary.opacity(0.15)
  @unknown default:         EmptyView()
  }
}
.frame(width: 64, height: 64)
.clipped()

