struct ItemDetail: View {
  let id: Item.ID
  @State private var model = DetailModel()

  var body: some View {
    Content(state: model.state)
      // Wrong: fires again on every pop back onto this screen
      // .onAppear { Task { await model.load(id) } }

      // Right: tied to the view's lifetime, restarted only when the id changes
      .task(id: id) { await model.load(id) }
  }
}

@Observable @MainActor
final class DetailModel {
  private(set) var state: LoadState = .idle

  func load(_ id: Item.ID) async {
    guard case .idle = state else { return }   // a second appearance is a no-op
    state = .loading
    do {
      state = .ready(try await api.item(id))   // URLSession honours cancellation
    } catch is CancellationError {
      state = .idle                            // the view left; let the next visit retry
    } catch {
      state = .failed(error)
    }
  }
}

// Cancellation is cooperative: this loop ignores it unless you ask
.task {
  for await tick in clock.ticks {
    if Task.isCancelled { break }
    model.advance(tick)
  }
}

// Wrong in a List: rows are recycled, so this runs on every scroll pass
ForEach(items) { item in
  Row(item: item).task { await load(item.id) }
}

