// A key is a default plus a rule for merging siblings
struct MaxHeightKey: PreferenceKey {
  static let defaultValue: CGFloat = 0
  static func reduce(value: inout CGFloat, nextValue: () -> CGFloat) {
    value = max(value, nextValue())
  }
}

struct EqualHeightCards: View {
  @State private var height: CGFloat = 0

  var body: some View {
    HStack(alignment: .top, spacing: 12) {
      ForEach(cards) { card in
        CardView(card)
          // Measuring in a background does not disturb the layout
          .background {
            GeometryReader { proxy in
              Color.clear.preference(key: MaxHeightKey.self, value: proxy.size.height)
            }
          }
          .frame(height: height > 0 ? height : nil)
      }
    }
    .onPreferenceChange(MaxHeightKey.self) { height = $0 }
  }
}

// iOS 18: the same measurement with no key, and it only fires on a real change
CardView(card)
  .onGeometryChange(for: CGSize.self) { $0.size } action: { size in
    model.cardSize = size
  }

// Anchors: the child hands up a rect, the ancestor resolves it in its own space
struct TabAnchors: PreferenceKey {
  static let defaultValue: [Tab.ID: Anchor<CGRect>] = [:]
  static func reduce(value: inout [Tab.ID: Anchor<CGRect>], nextValue: () -> [Tab.ID: Anchor<CGRect>]) {
    value.merge(nextValue()) { _, new in new }
  }
}

TabRow(tabs: tabs)          // each label: .anchorPreference(key: TabAnchors.self, value: .bounds) { [tab.id: $0] }
  .overlayPreferenceValue(TabAnchors.self) { anchors in
    GeometryReader { proxy in
      if let anchor = anchors[selection] {
        Capsule()
          .frame(width: proxy[anchor].width, height: 3)
          .offset(x: proxy[anchor].minX, y: proxy.size.height - 3)
      }
    }
  }

// Wrong: inside a List row, .automatic buttons inherit the row's tap region,
// so a single tap runs both actions and the row's navigation.
List(messages) { message in
  HStack {
    Text(message.title)
    Spacer()
    Button { star(message) } label: { Image(systemName: "star") }
    Button(role: .destructive) { delete(message) } label: { Image(systemName: "trash") }
  }
}

// Right: give the button its own hit region, move the destructive action where users expect it
List(messages) { message in
  NavigationLink(value: message) {
    HStack {
      Text(message.title)
      Spacer()
      Button { star(message) } label: { Image(systemName: "star") }
        .buttonStyle(.borderless)     // .plain also works; the row is no longer the target
    }
  }
  .swipeActions(edge: .trailing) {
    Button("Delete", role: .destructive) { delete(message) }
  }
}

// The opposite bug outside a List: only the drawn glyphs are tappable
HStack {
  Text("Filters")
  Spacer()                            // empty space, not a target
  Image(systemName: "chevron.right")
}
.padding()
.contentShape(.rect)                  // now the whole row responds
.onTapGesture { showFilters = true }

// Let touches fall through decoration
LinearGradient(colors: [.clear, .black], startPoint: .top, endPoint: .bottom)
  .allowsHitTesting(false)

