@Observable @MainActor
final class Router {
  var path: [Route] = []
  func popToRoot() { path.removeAll() }
}

struct RootView: View {
  @State private var router = Router()

  var body: some View {
    @Bindable var router = router
    NavigationStack(path: $router.path) {
      InboxView()
        .navigationDestination(for: Route.self) { Destination(route: $0) }
    }
    .environment(router)
  }
}

// Four screens deep: dismiss() would only pop one level
struct ConfirmView: View {
  @Environment(Router.self) private var router

  var body: some View {
    Button("Save") {
      Task {
        let item = try await save()
        router.path = [.item(item.id)]   // pop everything, land on the new item
      }
    }
  }
}

// A sheet is its own hierarchy: it needs its own stack and its own destinations
struct InboxView: View {
  @State private var editing: Draft?
  var body: some View {
    List { /* ... */ }
      .sheet(item: $editing) { draft in
        NavigationStack {
          EditView(draft: draft)
            .navigationDestination(for: EditRoute.self) { EditDestination(route: $0) }
        }
        .interactiveDismissDisabled(draft.isDirty)
      }
  }
}

// Inside the sheet, dismiss() closes the sheet itself
struct EditView: View {
  @Environment(\.dismiss) private var dismiss
  var body: some View {
    Button("Close") { dismiss() }
  }
}
